Let me break down the problem:

1. I need to validate if a string is a valid IPv4, IPv6, or neither
2. For IPv4:
   - Format: "x1.x2.x3.x4" (4 parts separated by dots)
   - Each part: 0 <= xi <= 255
   - No leading zeros (unless the number is just "0")
   - Each part must be digits only

3. For IPv6:
   - Format: "x1:x2:x3:x4:x5:x6:x7:x8" (8 parts separated by colons)
   - Each part: 1-4 characters
   - Hexadecimal (0-9, a-f, A-F)
   - Leading zeros are allowed

Let me write the solution:

```python
class Solution:
    def validIPAddress(self, queryIP: str) -> str:
        # Check if it's IPv4
        if '.' in queryIP:
            return self.checkIPv4(queryIP)
        # Check if it's IPv6
        elif ':' in queryIP:
            return self.checkIPv6(queryIP)
        else:
            return "Neither"

    def checkIPv4(self, ip: str) -> str:
        parts = ip.split('.')
        if len(parts) != 4:
            return "Neither"

        for part in parts:
            # Check if part is empty
            if not part:
                return "Neither"

            # Check if all characters are digits
            if not part.isdigit():
                return "Neither"

            # Check for leading zeros (except for "0" itself)
            if len(part) > 1 and part[0] == '0':
                return "Neither"

            # Check if number is in range 0-255
            num = int(part)
            if num < 0 or num > 255:
                return "Neither"

        return "IPv4"

    def checkIPv6(self, ip: str) -> str:
        parts = ip.split(':')
        if len(parts) != 8:
            return "Neither"

        for part in parts:
            # Check if part is empty
            if not part:
                return "Neither"

            # Check length (1-4 characters)
            if len(part) > 4:
                return "Neither"

            # Check if all characters are valid hexadecimal
            if not all(c in '0123456789abcdefABCDEF' for c in part):
                return "Neither"

        return "IPv6"
```

